+/// Split `s` into top-level chunks on a separator predicate, respecting quotes and
+/// `()`/`[]`/`{}` nesting.
+fn split_top_on(s: &str, is_sep: impl Fn(u8) -> bool) -> Vec<&str> {
+    let b = s.as_bytes();
+    let n = b.len();
+    let mut out = Vec::new();
+    let mut depth = 0i32;
+    let mut start = 0usize;
+    let mut i = 0;
+    while i < n {
+        match b[i] {
+            b'"' | b'\'' => {
+                i = skip_str(b, n, i);
+                continue;
+            }
+            b'(' | b'[' | b'{' => depth += 1,
+            b')' | b']' | b'}' => depth -= 1,
+            c if depth == 0 && is_sep(c) => {
+                out.push(&s[start..i]);
+                start = i + 1;
+            }
+            _ => {}
+        }
+        i += 1;
+    }
+    out.push(&s[start..]);
+    out
+}
